-- seed_universe_v1_rollback.sql
-- Exact rollback for seed_universe_v1.sql. Reverse dependency order, scoped
-- ONLY to the hardcoded seed UUIDs (org ids 5eed0001-..., party ids
-- 5eed0002-...). Never touches Kansas Fitness Physio, South Park Physician
-- Group, or any other org.
--
-- NOTE: dependent tables are deleted by seeded org_id so the org DELETE can
-- succeed even if extra memberships/statuses/role assignments were later
-- added to a seed org through the app. If other data was created under a
-- seed org (providers, cases, audit_log rows, ...), the org DELETE below
-- fails loudly on its FK - remove that data deliberately first; nothing here
-- cascades into it silently.

BEGIN;

DELETE FROM public.status_configs WHERE org_id IN (
  '5eed0001-0000-4000-a000-000000000001',
  '5eed0001-0000-4000-a000-000000000002',
  '5eed0001-0000-4000-a000-000000000003',
  '5eed0001-0000-4000-a000-000000000004',
  '5eed0001-0000-4000-a000-000000000005',
  '5eed0001-0000-4000-a000-000000000006',
  '5eed0001-0000-4000-a000-000000000007',
  '5eed0001-0000-4000-a000-000000000008',
  '5eed0001-0000-4000-a000-000000000009',
  '5eed0001-0000-4000-a000-000000000010',
  '5eed0001-0000-4000-a000-000000000011'
);

DELETE FROM public.memberships WHERE org_id IN (
  '5eed0001-0000-4000-a000-000000000001',
  '5eed0001-0000-4000-a000-000000000002',
  '5eed0001-0000-4000-a000-000000000003',
  '5eed0001-0000-4000-a000-000000000004',
  '5eed0001-0000-4000-a000-000000000005',
  '5eed0001-0000-4000-a000-000000000006',
  '5eed0001-0000-4000-a000-000000000007',
  '5eed0001-0000-4000-a000-000000000008',
  '5eed0001-0000-4000-a000-000000000009',
  '5eed0001-0000-4000-a000-000000000010',
  '5eed0001-0000-4000-a000-000000000011'
);

DELETE FROM public.party_role_assignments WHERE org_id IN (
  '5eed0001-0000-4000-a000-000000000001',
  '5eed0001-0000-4000-a000-000000000002',
  '5eed0001-0000-4000-a000-000000000003',
  '5eed0001-0000-4000-a000-000000000004',
  '5eed0001-0000-4000-a000-000000000005',
  '5eed0001-0000-4000-a000-000000000006',
  '5eed0001-0000-4000-a000-000000000007',
  '5eed0001-0000-4000-a000-000000000008',
  '5eed0001-0000-4000-a000-000000000009',
  '5eed0001-0000-4000-a000-000000000010',
  '5eed0001-0000-4000-a000-000000000011'
);

DELETE FROM public.parties WHERE id IN (
  '5eed0002-0000-4000-a000-000000000001',
  '5eed0002-0000-4000-a000-000000000002',
  '5eed0002-0000-4000-a000-000000000003',
  '5eed0002-0000-4000-a000-000000000004',
  '5eed0002-0000-4000-a000-000000000005',
  '5eed0002-0000-4000-a000-000000000006',
  '5eed0002-0000-4000-a000-000000000007',
  '5eed0002-0000-4000-a000-000000000008',
  '5eed0002-0000-4000-a000-000000000009',
  '5eed0002-0000-4000-a000-000000000010',
  '5eed0002-0000-4000-a000-000000000011'
);

DELETE FROM public.organizations WHERE id IN (
  '5eed0001-0000-4000-a000-000000000001',
  '5eed0001-0000-4000-a000-000000000002',
  '5eed0001-0000-4000-a000-000000000003',
  '5eed0001-0000-4000-a000-000000000004',
  '5eed0001-0000-4000-a000-000000000005',
  '5eed0001-0000-4000-a000-000000000006',
  '5eed0001-0000-4000-a000-000000000007',
  '5eed0001-0000-4000-a000-000000000008',
  '5eed0001-0000-4000-a000-000000000009',
  '5eed0001-0000-4000-a000-000000000010',
  '5eed0001-0000-4000-a000-000000000011'
);

COMMIT;
